// ============================================================
// Helper Functions
// ============================================================

function getFileById(id) {
    return courseFiles.find(f => f.id === id);
}

function getFilesByExtension(ext) {
    return courseFiles.filter(f => f.id.endsWith('.' + ext));
}

function getFilesByPath(path) {
    return courseFiles.filter(f => f.path.includes(path));
}

function getTotalSize() {
    return courseFiles.reduce((sum, f) => sum + f.size, 0);
}

function getFileCount() {
    return courseFiles.length;
}

// ============================================================
// Exports
// ============================================================

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { 
        courseFiles, 
        getFileById, 
        getFilesByExtension, 
        getFilesByPath,
        getTotalSize,
        getFileCount
    };
}

if (typeof window !== 'undefined') {
    window.courseFiles = courseFiles;
    window.getFileById = getFileById;
    window.getFilesByExtension = getFilesByExtension;
    window.getFilesByPath = getFilesByPath;
    window.getTotalSize = getTotalSize;
    window.getFileCount = getFileCount;
}

console.log('📁 Course files loaded: ' + getFileCount() + ' files');
console.log('📊 Total size: ' + (getTotalSize() / (1024 * 1024)).toFixed(1) + ' MB');

// Show .cur file count
const curFiles = getFilesByExtension('cur');
if (curFiles.length > 0) {
    console.log('🖱️  .cur files found: ' + curFiles.length);
    console.log('   - ' + curFiles.map(f => f.path).join('\n   - '));
}
